(function(root){
'use strict';
const D=typeof module!=='undefined'?require('./data.js'):root.KEEPER_DATA;
const E=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const normalize=v=>String(v).normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase();
const pageById=id=>D.pages.find(p=>p.id===id)||D.pages[0];
const can=(id,ctx)=>{const p=pageById(id),r=D.roles[ctx.role]||D.roles.admin;return r.all||r.ids.includes(p.parent||p.id);};
const canEdit=ctx=>!!D.roles[ctx.role]?.edit;
const scoped=(rows,ctx)=>ctx.role==='coordinacion'?rows.filter(r=>r.site===D.sites[0]):rows;
const C=options=>({role:'admin',state:'normal',id:null,filters:{},page:1,...options});
const paths={index:'M3 11 12 3l9 8M5 10v11h5v-6h4v6h5V10',equipos:'M3 4h18v13H3zM8 21h8M12 17v4',usuarios:'M16 21v-2a4 4 0 0 0-4-4H6a4 4 0 0 0-4 4v2M13 7a4 4 0 1 1-8 0 4 4 0 0 1 8 0M17 4a4 4 0 0 1 0 7M22 21v-2a4 4 0 0 0-3-3.9',sedes:'M4 21V3h12v18M16 9h4v12M2 21h20M8 7h4M8 11h4M8 15h4M9 21v-3h3v3',pendientes:'M12 8v4l3 2M22 12a10 10 0 1 1-20 0 10 10 0 0 1 20 0',reportes:'M4 20V10h4v10M10 20V4h4v16M16 20v-7h4v7',reglas:'M12 3 3 7v5c0 5 9 9 9 9s9-4 9-9V7zM8 12l3 3 5-6',roles:'M5 10h14v11H5zM8 10V6a4 4 0 0 1 8 0v4M12 14v3',releases:'M12 16V3M7 8l5-5 5 5M4 16v5h16v-5',ajustes:'M4 6h16M4 12h16M4 18h16M8 3v6M16 9v6M10 15v6',logs:'M5 3h10l4 4v14H5zM15 3v5h4M8 12h8M8 16h8',menu:'M4 6h16M4 12h16M4 18h16',close:'m6 6 12 12M6 18 18 6',arrow:'M5 12h14m-5-5 5 5-5 5',search:'M16 16l5 5M18 10a8 8 0 1 1-16 0 8 8 0 0 1 16 0',plus:'M12 5v14M5 12h14'};
function icon(id){return `<svg class="icon" aria-hidden="true" viewBox="0 0 24 24"><path d="${paths[id]||paths.logs}"/></svg>`;}
function badge(value){const s=String(value);const type=/^(Aplicado|En línea|Activo|Activa|Operativo|A tiempo|Estable|Permitido|Habilitada)$/.test(s)?'good':/^(Fallido|Error|Denegado|Revocado|Rechazada)$/.test(s)?'bad':/^(Pendiente|Tarde|Aviso|Atención|Por revisar|No soportado|Sin conexión|Pendiente de actualizar)$/.test(s)?'warn':/^(En curso|En revisión|Profesional|Borrador|Vista previa)$/.test(s)?'info':'';return `<span class="badge ${type}">${E(s)}</span>`;}
function href(id,ctx,extra={}){const q=new URLSearchParams({...extra});if(ctx.role!=='admin')q.set('role',ctx.role);return `${id}.html${q.size?'?'+q:''}`;}
function link(id,text,ctx,extra={},cls=''){if(!can(id,ctx))return `<span class="muted">${E(text)}</span>`;return `<a class="${cls}" href="${E(href(id,ctx,extra))}">${E(text)}</a>`;}
function nav(page,ctx){return D.groups.map((g,i)=>{const list=D.pages.filter(p=>p.group===g&&can(p.id,ctx));if(!list.length)return '';const items=list.map(p=>`<a class="nav-link" href="${E(href(p.id,ctx))}"${(page.parent||page.id)===p.id?' aria-current="page"':''}>${icon(p.id)}<span class="nav-label">${E(p.title)}${p.future?'<small>Próximamente</small>':''}</span>${p.id==='pendientes'?`<span class="count" data-pending-count>${D.pending.filter(p=>p.status==='Pendiente').length}</span>`:''}</a>`).join('');return i>0?`<details class="nav-group" ${i<4||page.group===g?'open':''}><summary class="nav-heading">${E(g)}</summary>${items}</details>`:`<section class="nav-group"><p class="nav-heading">${E(g)}</p>${items}</section>`;}).join('');}
function kpis(items){return `<dl class="kpis">${items.map(([label,value,note,ic])=>`<div class="kpi"><dt>${icon(ic||'reportes')}${E(label)}</dt><dd>${E(value)}</dd><small>${E(note)}</small></div>`).join('')}</dl>`;}
function facts(items,one=false){return `<dl class="facts${one?' one':''}">${items.map(([k,v])=>`<div><dt>${E(k)}</dt><dd>${v}</dd></div>`).join('')}</dl>`;}
function panel(title,content,aside=''){return `<section class="surface"><div class="section-head"><h2>${E(title)}</h2>${aside}</div>${content}</section>`;}
function bars(items){return `<div class="bars">${items.map(([name,n,note])=>`<div class="bar-row"><div class="bar-label"><span>${E(name)}</span><strong>${n}%</strong></div><div class="bar-track"><div class="bar-fill" style="width:${Number(n)}%"></div></div>${note?`<small>${E(note)}</small>`:''}</div>`).join('')}</div>`;}
function chart(){const pts=col=>D.activity.map((r,i)=>`${45+i*78},${200-r[col]*1.6}`).join(' ');return `<figure class="no-margin"><svg class="chart" viewBox="0 0 565 240" role="img" aria-label="Actividad y foco, del 23 al 29 de septiembre de 2026. Porcentaje del tiempo registrado.">${[0,25,50,75,100].map(n=>`<path class="grid" d="M40 ${200-n*1.6}H540"/><text x="4" y="${204-n*1.6}">${n}%</text>`).join('')}<polyline class="series" points="${pts(1)}"/><polyline class="series secondary" points="${pts(2)}"/>${D.activity.map((r,i)=>`<circle cx="${45+i*78}" cy="${200-r[1]*1.6}" r="3.5" fill="var(--accent)"/><text x="${45+i*78}" y="226" text-anchor="middle">${r[0]}</text>`).join('')}</svg><figcaption class="legend"><span>Tiempo activo</span><span>Tiempo en foco</span></figcaption><details class="spaced"><summary class="help">Consultar valores del gráfico</summary><div class="table-wrap"><table><caption>Porcentaje del tiempo registrado · muestra</caption><thead><tr><th>Día</th><th>Activo</th><th>Foco</th></tr></thead><tbody>${D.activity.map(r=>`<tr><td>${r[0]}</td><td>${r[1]}%</td><td>${r[2]}%</td></tr>`).join('')}</tbody></table></div></details></figure>`;}
function model(id,ctx){
 if(id==='equipos')return {columns:['Equipo','Persona','Sede','Estado','Agente','Última conexión'],rows:scoped(D.devices,ctx).map(d=>[d.hostname,D.people.find(p=>p.id===d.personId)?.name||'Sin asignar',d.site,d.status,d.version,d.lastSeen]),ids:scoped(D.devices,ctx).map(d=>d.id),target:'equipo',filters:[[3,'Estado'],[2,'Sede'],[4,'Agente']]};
 if(id==='usuarios')return {columns:['Persona','Área','Sede','Tier','Estado'],rows:scoped(D.people,ctx).map(p=>[p.name,p.area,p.site,p.tier,p.status]),ids:scoped(D.people,ctx).map(p=>p.id),target:'miembro',filters:[[2,'Sede'],[1,'Área'],[3,'Tier']]};
 if(id==='pendientes')return {columns:['Persona','Equipo','Sede','Solicitud','Estado'],rows:scoped(D.pending,ctx).map(p=>[p.name,p.hostname,p.site,p.date,p.status]),filters:[[4,'Estado'],[2,'Sede']]};
 if(id==='reportes'||id==='rankings')return {columns:['Persona','Área','Sede','Tiempo activo','Foco'],rows:scoped(D.people,ctx).slice(0,24).sort((a,b)=>b.focus-a.focus).map(p=>[p.name,p.area,p.site,Math.floor(p.activeMinutes/60)+' h '+p.activeMinutes%60+' min',p.focus+'%']),filters:[[2,'Sede'],[1,'Área']]};
 if(id==='sedes')return {columns:['Sede','Equipos','En línea','Sin conexión','Personas'],rows:D.sites.filter(s=>ctx.role!=='coordinacion'||s===D.sites[0]).map(s=>[s,D.devices.filter(d=>d.site===s).length,D.devices.filter(d=>d.site===s&&d.status==='En línea').length,D.devices.filter(d=>d.site===s&&d.status!=='En línea').length,D.people.filter(p=>p.site===s).length]),filters:[]};
 if(id==='endurecimiento')return {columns:['Equipo','Persona','Sede','Modo B','Último contacto'],rows:scoped(D.devices,ctx).map(d=>[d.hostname,D.people.find(p=>p.id===d.personId)?.name||'Sin asignar',d.site,d.hardening,d.lastSeen]),ids:scoped(D.devices,ctx).map(d=>d.id),target:'equipo',filters:[[3,'Modo B'],[2,'Sede']]};
 const t=D.tables[id];if(!t)return null;
 let rows=t.rows;const si=t.columns.indexOf('Sede');if(ctx.role==='coordinacion'&&si>=0)rows=rows.filter(r=>r[si]===D.sites[0]);
 const options={organizacion:[[1,'Tipo']],logs:[[3,'Nivel'],[2,'Módulo']],integraciones:[[1,'Tipo']],asignaciones:[[2,'Sede'],[3,'Área']],presencia:[[4,'Estado'],[1,'Sede']],auditoria:[[4,'Resultado']],reglas:[[1,'Alcance']],roles:[[1,'Alcance']],tiers:[[3,'Estado']]};
 return {...t,rows,filters:options[id]||[[t.columns.length-1,t.columns.at(-1)]]};
}
function filtered(m,ctx){let rows=m.rows.map((cells,index)=>({cells,index}));if(ctx.filters.q)rows=rows.filter(r=>normalize(r.cells.join(' ')).includes(normalize(ctx.filters.q)));for(const [key,value]of Object.entries(ctx.filters))if(key!=='q'&&value)rows=rows.filter(r=>String(r.cells[Number(key)])===value);return rows;}
function tableRows(m,ctx){const all=filtered(m,ctx),last=Math.max(1,Math.ceil(all.length/12));ctx.page=Math.max(1,Math.min(ctx.page,last));const slice=all.slice((ctx.page-1)*12,ctx.page*12);if(!all.length)return `<div class="empty"><h2>No hay coincidencias</h2><p>Prueba otro nombre o elimina los filtros para ver todos los registros de tu alcance.</p><button data-action="clear-filters">Limpiar filtros</button></div>`;
 return `<div class="table-wrap" tabindex="0" aria-label="Tabla con desplazamiento horizontal"><table><caption>${E(m.note||'Datos ficticios · '+D.asOf+' · America/Bogota')}</caption><thead><tr>${m.columns.map(c=>`<th scope="col">${E(c)}</th>`).join('')}<th scope="col">Detalle</th></tr></thead><tbody>${slice.map(({cells,index})=>`<tr>${cells.map((cell,i)=>`<td>${i===0&&m.target?link(m.target,cell,ctx,{id:m.ids[index]}):/^(Activo|Activa|En línea|Sin conexión|Aplicado|Fallido|Pendiente|A tiempo|Tarde|Error|Aviso|Operativo|Atención|Borrador|En curso|En revisión|Por revisar|Denegado|Permitido|Profesional|Vista previa|Sin registro|Revocado|Aprobada|Rechazada)$/.test(String(cell))?badge(cell):E(cell)}</td>`).join('')}<td>${m.target?link(m.target,'Ver ficha',ctx,{id:m.ids[index]}):`<button class="link-button" data-action="row" data-index="${index}" aria-label="Ver detalle de ${E(cells[0])}">Ver detalle</button>`}</td></tr>`).join('')}</tbody></table></div><div class="pagination"><span role="status">${(ctx.page-1)*12+1}–${Math.min(ctx.page*12,all.length)} de ${all.length} registros</span><button data-action="prev" ${ctx.page===1?'disabled':''}>Anterior</button><span>Página ${ctx.page} / ${last}</span><button data-action="next" ${ctx.page===last?'disabled':''}>Siguiente</button></div>`;
}
function table(id,ctx,title='Registros'){const m=model(id,ctx);if(!m)return '';return panel(title,`<div class="toolbar"><label>Buscar<input type="search" data-filter="q" value="${E(ctx.filters.q||'')}" placeholder="Nombre, equipo o palabra clave"></label>${m.filters.map(([col,label])=>`<label>${E(label)}<select data-filter="${col}"><option value="">Todos</option>${[...new Set(m.rows.map(r=>String(r[col])))].sort().map(v=>`<option${ctx.filters[col]===v?' selected':''}>${E(v)}</option>`).join('')}</select></label>`).join('')}<button data-action="clear-filters">Limpiar</button></div><div id="table-results">${tableRows(m,ctx)}</div>`);}
function dashboard(ctx){const ds=scoped(D.devices,ctx),ps=scoped(D.people,ctx),on=ds.filter(d=>d.status==='En línea').length;return kpis([['Equipos en línea',on,`${ds.length} equipos registrados`,'equipos'],['Sin conexión',ds.length-on,'Revisar último contacto','equipos'],['Actividad de hoy','81%','Sobre el tiempo registrado','reportes'],['Accesos pendientes',D.pending.filter(p=>p.status==='Pendiente').length,'Esperando autorización','pendientes']])+`<div class="split">${panel('Actividad de la semana',`<p class="help">${D.period.label} · Tiempo activo y tiempo en foco</p>${chart()}`,link('reportes','Abrir reportes',ctx))}${panel('Necesita tu atención',D.alerts.filter(a=>can(a[2].split('.')[0],ctx)).map(([t,d,h])=>`<article class="alert-item"><strong>${E(t)}</strong><p>${E(d)}</p><a href="${E(h+(ctx.role==='admin'?'':(h.includes('?')?'&':'?')+'role='+ctx.role))}">Revisar ${icon('arrow')}</a></article>`).join(''))}</div><div class="split equal">${panel('Aplicaciones más usadas',bars(D.apps),link('rankings','Ver clasificación',ctx))}${panel('Personas y cobertura',facts([['Personas activas',ps.length],['Sedes',ctx.role==='coordinacion'?1:D.sites.length],['Política base',E(D.devices[0].policy)],['Última actualización',E(D.asOf)]]),link('usuarios','Ver personas',ctx))}</div>`;}
function devicePage(ctx){const d=scoped(D.devices,ctx).find(d=>d.id===(ctx.id||'d1'));if(!d)return missing('equipo',ctx);const p=D.people.find(p=>p.id===d.personId),controls=D.controls.map(r=>[...r]);if(d.version==='Sin reporte'){controls.forEach(r=>{r[1]='Desconocido';r[2]='Esperando el primer reporte del agente';});}else if(!d.os.includes('Home'))controls[2]=['InstallEnforcer','Aplicado','Reglas AppLocker por editor firmado'];return `<div class="identity"><div class="avatar">${icon('equipos')}</div><div><h2>${E(d.hostname)}</h2><p>${E(d.site)} · ${E(d.os)}</p></div>${badge(d.status)}</div><div class="split">${panel('Resumen del equipo',facts([['Persona asignada',link('miembro',p.name,ctx,{id:p.id})],['Versión del agente',E(d.version)],['Última conexión',E(d.lastSeen)],['Sistema / edición',E(d.os)],['Procesador',E(d.cpu)],['Memoria RAM',E(d.ram)],['Disco',E(d.disk)+' · '+d.free+' GB libres'],['Política aplicada',link('reglas',d.policy,ctx)],['Anillo de actualización',E(d.ring)],['Modo B',link('endurecimiento',d.hardening,ctx,{id:d.id})]]))}${panel('Acciones remotas',`<p class="help">Las órdenes esperan confirmación del agente. Un equipo sin conexión las recibe cuando vuelva a conectarse.</p>${canEdit(ctx)?`<div class="actions">${['Bloquear','Desbloquear','Reiniciar','Apagar'].map(a=>`<button data-action="command" data-command="${a}" data-device="${d.id}">${a}</button>`).join('')}</div><div class="danger-zone"><h3>Borrado remoto</h3><p>Elimina los datos del equipo. Requiere escribir el nombre completo y un motivo.</p><button class="danger" data-action="command" data-command="Borrar" data-device="${d.id}">Borrar equipo…</button></div>`:'<div class="notice spaced">Este perfil solo puede consultar el equipo.</div>'}<div class="spaced">${link('pin','Bloqueo con PIN · Próximamente',ctx)}</div>` )}</div>${panel('Estado por control',`<div class="control-grid" id="controles" tabindex="-1">${controls.map(([name,state,detail])=>`<div class="control-row"><div><strong>${name}</strong>${badge(state)}</div><p>${E(detail)}</p></div>`).join('')}</div><p class="help spaced">El estado describe el último reporte del agente. «Desconocido» no equivale a «Aplicado».</p>`)}${panel('Registro reciente del agente',`<ul class="timeline">${D.tables.logs.rows.filter(r=>r[1]===d.hostname).map(r=>`<li><time>${E(r[0].split(' · ')[1])}</time><div><strong>${E(r[2])} · ${E(r[3])}</strong><small>${E(r[4])}</small></div></li>`).join('')||'<li>Sin registros recientes para este equipo en la muestra.</li>'}</ul>`,link('logs','Abrir logs del cliente',ctx,{q:d.hostname}))}`;}
function missing(type,ctx){return `<div class="empty state-error"><h2>No se encontró la ficha</h2><p>El identificador no existe en esta muestra o está fuera del alcance de tu perfil.</p>${link(type==='equipo'?'equipos':'usuarios','Volver al listado',ctx,{},'button')}</div>`;}
function personPage(ctx){const p=scoped(D.people,ctx).find(p=>p.id===(ctx.id||'p1'));if(!p)return missing('persona',ctx);const ds=D.devices.filter(d=>d.personId===p.id);return `<div class="identity"><div class="avatar">${E(p.name.split(' ').slice(0,2).map(n=>n[0]).join(''))}</div><div><h2>${E(p.name)}</h2><p>${E(p.position)} · ${E(p.site)}</p></div>${badge(p.status)}</div>${kpis([['Actividad registrada',Math.floor(p.activeMinutes/60)+' h '+p.activeMinutes%60+' min','Muestra del '+D.period.personDay],['Tiempo en foco',p.focus+'%','Del tiempo registrado'],['Presencia de hoy',p.presence,'Entrada: '+(p.presence==='Sin registro'?'sin registro':p.entry),'pendientes'],['Equipos',ds.length,'Vinculados a esta persona','equipos']])}<div class="split">${panel('Datos de la persona',facts([['Correo',E(p.email)],['Área',E(p.area)],['Sede',E(p.site)],['Cargo',E(p.position)],['Tier / suscripción',badge(p.tier)],['Vigencia de la muestra','Hasta '+D.period.end]]))}${panel('Equipos asignados',ds.map(d=>`<article class="alert-item"><strong>${link('equipo',d.hostname,ctx,{id:d.id})}</strong><p>${E(d.os)} · agente ${E(d.version)}</p>${badge(d.status)}</article>`).join(''))}</div><div class="split equal">${panel('Productividad',bars([['Tiempo en foco',p.focus,'Muestra individual · '+D.period.personDay],['Fuera de foco',100-p.focus,'Porcentaje restante del tiempo registrado']]))}${panel('Presencia y jornada',facts([['Horario','08:00–17:00'],['Entrada de hoy',p.presence==='Sin registro'?'Sin registro':E(p.entry)],['Resultado',badge(p.presence)],['Zona horaria',E(D.timezone)]]),link('presencia','Ver asistencia',ctx,{q:p.name}))}</div>`;}
function supplementary(id,ctx){
 if(id==='reglas')return panel('Controles de la política base',`<div class="control-grid">${D.policyExamples.map(([n,d,s])=>`<div class="control-row"><div><strong>${E(n)}</strong>${badge('Activa')}</div><p>${E(d)}</p><p>${E(s)}</p></div>`).join('')}</div><div class="notice spaced no-margin">Precedencia de muestra: equipo → persona → área → empresa. La ficha de equipo muestra la política efectiva y su resultado.</div>`);
 if(id==='releases')return panel('Despliegue de 4.0.3',`<div class="three">${D.rings.map(([n,total,done],i)=>`<article class="ring"><span>ANILLO ${i+1}</span><h3>${n}</h3><p>${total} equipos asignados</p><div class="bar-track"><div class="bar-fill" style="width:${done/total*100}%"></div></div><strong>${done} / ${total} actualizados</strong><p>${i<2?'Validación completada':'En curso · 60 pendientes'}</p></article>`).join('')}</div><p class="help spaced">Paquete de muestra con firma y hash verificados. Cada anillo requiere revisión antes de ampliar el alcance.</p>`);
 if(id==='salud')return kpis([['CPU',D.health.cpu+'%','Carga de la muestra'],['Memoria',D.health.ram+'%','Capacidad utilizada'],['Disco',D.health.disk+'%','Capacidad utilizada'],['Servicios','4 / 5','Una cola requiere atención']]);
 if(id==='cobertura'){const installed=D.devices.length,missing=D.tables.cobertura.rows.length,total=installed+missing;return kpis([['Puestos previstos',total,'Inventario de muestra'],['Con agente',installed,'Equipos registrados'],['Por instalar',missing,'Puestos por revisar'],['Cobertura',(installed/total*100).toFixed(1).replace('.',',')+'%',installed+' de '+total+' puestos']]);}
 if(id==='presencia'){const p=scoped(D.people,ctx);return kpis([['Personas',p.length,'En el alcance'],['A tiempo',p.filter(p=>p.presence==='A tiempo').length,'Entrada hasta 08:00'],['Tarde',p.filter(p=>p.presence==='Tarde').length,'Revisar justificación'],['Sin registro',p.filter(p=>p.presence==='Sin registro').length,'No equivale a ausencia']]);}
 if(id==='reportes'||id==='rankings')return `<div class="notice">Período de muestra: ${D.period.label}. La actividad registrada es una señal operativa, no una evaluación de desempeño.</div><div class="split equal">${panel(id==='rankings'?'Comparativa por área':'Actividad y foco',id==='rankings'?bars(D.areaActivity):chart())}${panel('Top de aplicaciones',bars(D.apps))}</div>`;
 if(id==='sedes')return `<div class="three">${D.sites.filter(s=>ctx.role!=='coordinacion'||s===D.sites[0]).map(s=>panel(s,`<p class="eyebrow">Operación de sede</p><p style="font-size:36px;color:var(--accent);margin:15px 0">${D.devices.filter(d=>d.site===s&&d.status==='En línea').length} <small>en línea / ${D.devices.filter(d=>d.site===s).length}</small></p><p class="help">${D.people.filter(p=>p.site===s).length} personas · ${D.devices.filter(d=>d.site===s&&d.status!=='En línea').length} equipos sin conexión</p><div class="spaced">${link('equipos','Ver equipos de la sede',ctx,{site:s},'button')}</div>`)).join('')}</div>`;
 if(id==='turnos')return panel(D.period.weekTitle,`<p class="help">Vista previa del turno administrativo · la jornada se interpreta en America/Bogota.</p><div class="week">${D.period.week.map(d=>`<div><strong>${d}</strong><span>08:00–17:00</span><span>Pausa · 1 hora</span></div>`).join('')}</div>`);
 if(id==='puertas')return panel('Recorrido de entrada',`<div class="portal-path"><span>1. Punto de acceso</span><span>2. Identificar persona</span><span>3. Registrar hora y sede</span></div><p class="help">Vista previa: puerta física o ubicación declarada. No se solicita GPS ni se registra la ubicación de este navegador.</p>`);
 if(id==='integraciones')return `<div class="split equal">${panel('Claves API',facts([['Referencia',E(D.integrationSample.key)+' · sin secreto'],['Alcance','Lectura de personas y organización'],['Caducidad','30 sep 2026']])+`<div class="actions"><button class="danger" data-action="revoke" data-target="${D.integrationSample.key}">Revocar clave…</button></div>`)}${panel('Webhooks',facts([['Destino',E(D.integrationSample.destination)],['Evento',E(D.integrationSample.event)],['Entrega de muestra',E(D.integrationSample.lastDelivery)]])+`<p class="help spaced">3 intentos previstos con espera progresiva. No se envían solicitudes.</p>`)}</div>`;
 if(id==='tiers'||id==='suscripciones')return `<div class="three">${D.tables.tiers.rows.map(r=>panel(r[0],`<p style="font-size:32px;color:var(--accent)">${E(r[1])} <small>personas</small></p><p class="help spaced">${E(r[2])}</p>`)).join('')}</div>`;
 if(['tareas','casos','recepcion','contratar'].includes(id)){const labels={tareas:['Por hacer','En curso','En revisión','Completada'],casos:['Solicitud','Asignación','Revisión','Entrega'],recepcion:['Entrada','Clasificación','Derivación','Cierre'],contratar:['Necesidad','Validación','Selección','Incorporación']}[id];return panel('Flujo de trabajo previsto',`<div class="portal-path">${labels.map((s,i)=>`<span>${i+1}. ${s}</span>`).join('')}</div><p class="help">Las solicitudes de esta pantalla son una vista previa del portal cliente futuro.</p>`);}
 if(id==='doble-empleo')return `<div class="notice">Una coincidencia puede tener una explicación laboral válida. Revisa fechas, actividad y contexto antes de marcar una señal como revisada o descartada.</div>`;
 if(id==='organizacion')return panel('Estructura de la empresa',`<div class="portal-path"><span>${E(D.company)}</span><span>3 sedes</span><span>4 áreas</span><span>Catálogo de cargos</span></div><p class="help">Filtra por «Tipo» para consultar sedes, áreas o cargos.</p>`);
 return '';
}
function rolePage(ctx){return `<div class="gates"><section class="gate"><p class="eyebrow">Autorización 1 · Empresa</p><h3>Autogestión habilitada</h3><p>La autoridad central habilita la administración de roles para esta empresa.</p><label class="check"><input type="checkbox" id="gate-company" ${D.gateCompany?'checked':''}> Simular habilitación de empresa</label></section><section class="gate"><p class="eyebrow">Autorización 2 · Persona</p><h3>Permiso roles.gestionar</h3><p>La persona debe recibir el permiso explícito para administrar roles.</p><label class="check"><input type="checkbox" id="gate-permission" ${D.gatePermission?'checked':''}> Simular permiso delegado</label></section></div><div class="notice" id="gate-status">${D.gateCompany&&D.gatePermission?'Ambas autorizaciones están habilitadas. Puedes crear un rol de muestra.':'La edición está bloqueada. Se necesitan las dos autorizaciones.'}</div>${table('roles',ctx,'Roles de Grupo AZC')}<p class="help">Los interruptores son herramientas de revisión del prototipo. En el producto, un administrador de empresa no puede concederse estas autorizaciones.</p>`;}
function settingsPage(){return `<div class="split equal">${panel('Marca de Grupo AZC',`<form id="brand-form"><div class="form-grid"><label class="wide">Nombre visible<input name="company" required value="${E(D.company)}"></label><label>Color principal<input name="primary" type="color" value="${D.brand.primary}"></label><label>Acento de marca<input name="accent" type="color" value="${D.brand.accent}"></label><label class="wide">Zona horaria<select name="timezone"><option>America/Bogota</option></select></label></div><p class="help spaced">La configuración se guarda por empresa en esta muestra. El fondo del panel siempre es claro.</p><p id="brand-error" class="error-text" hidden></p></form>`)}${panel('Vista previa de la marca',`<div class="brand-preview" id="brand-preview"><img src="logo-main.png" width="447" height="172" alt="Grupo AZC"><h3 id="preview-name">${E(D.company)}</h3><p>Un espacio para administrar tu operación.</p><span class="sample-action">Acción principal</span></div><p class="help spaced">Logotipo oficial copiado de los recursos locales de v4.</p>`)}</div>`;}
function hardeningPage(ctx){const d=D.devices.find(d=>d.id===(ctx.id||'d1'))||D.devices[0];return `<div class="notice">Modo B: la persona trabaja como usuario estándar. Antes de aplicar, verifica la cuenta de soporte, la custodia de recuperación y el punto de restauración.</div><div class="split equal">${panel('Configuración de recuperación',facts([['Cuenta local de soporte',E(D.hardening.account)],['Modo',E(D.hardening.mode)],['Custodia',E(D.hardening.recovery)],['Última rotación',E(D.hardening.rotation)]]))}${panel('Equipo seleccionado',facts([['Equipo',link('equipo',d.hostname,ctx,{id:d.id})],['Estado de Modo B',badge(d.hardening)],['Punto de restauración',E(D.hardening.restore)]])+`<div class="actions"><button data-action="harden-device" data-device="${d.id}">Revisar aplicación…</button><button class="danger" data-action="revert-hardening" data-device="${d.id}">Revertir Modo B…</button></div>`)}</div>${table('endurecimiento',ctx,'Endurecimiento por equipo')}`;}
function capturePage(ctx){return `<div class="notice">Vista previa de evidencias: las miniaturas son documentos dibujados con HTML y CSS. No se captura ninguna pantalla real.</div><div class="three">${D.screenshots.map(([time,app,caption],i)=>`<button class="capture" data-action="capture" data-index="${i}"><div class="capture-screen"><div class="window-top">${E(app)}</div><div class="document-mock"><span></span><span></span><span></span><span></span><span></span></div></div><div class="capture-caption"><strong>29 sep 2026 · ${time}</strong><small>${E(D.devices[0].hostname)} · ${E(caption)}</small><small>Abrir vista previa</small></div></button>`).join('')}</div>`;}
function pinPage(ctx){return `<div class="split equal">${panel('Bloqueo asistido',facts([['Equipo de muestra',link('equipo',D.devices[0].hostname,ctx,{id:'d1'})],['Persona',E(D.people[0].name)],['Vigencia propuesta',D.pinConfig.minutes+' minutos'],['Intentos máximos',D.pinConfig.attempts]])+`<p class="help spaced">El código temporal se comunicaría por un canal autorizado. El prototipo solo prepara un borrador.</p>`)}${panel('Experiencia en el equipo',`<div class="brand-preview"><img src="logo-main.png" alt="Grupo AZC"><h3>Este equipo está bloqueado</h3><p>Contacta a soporte e indica la referencia de tu equipo.</p><label class="spaced">PIN temporal<input inputmode="numeric" maxlength="6" placeholder="6 dígitos" aria-label="Vista previa del PIN temporal" disabled></label><p class="help">Vista previa no interactiva de la pantalla del agente.</p></div>`)}</div>`;}
function content(page,ctx){if(!can(page.id,ctx))return `<div class="empty state-error"><h2>Tu perfil no tiene acceso a esta sección</h2><p>El menú muestra los módulos permitidos. Puedes cambiar el perfil desde «Revisar prototipo».</p>${link('index','Volver al inicio',ctx,{},'button')}</div>`;
 if(ctx.state!=='normal')return `<div class="empty ${ctx.state==='error'?'state-error':''}" role="${ctx.state==='error'?'alert':'status'}"><h2>${ctx.state==='error'?'No se pudo cargar la información':'Aún no hay información'}</h2><p>${ctx.state==='error'?'La consulta no está disponible en este escenario de muestra. Puedes reintentar sin perder tu ubicación.':'Esta empresa todavía no tiene registros en la sección. Cuando existan, aparecerán aquí.'}</p><button data-action="restore">${ctx.state==='error'?'Reintentar':'Volver a los datos de muestra'}</button></div>`;
 const funcs={index:dashboard,equipo:devicePage,miembro:personPage,roles:rolePage,ajustes:settingsPage,endurecimiento:hardeningPage,capturas:capturePage,pin:pinPage};return funcs[page.id]?funcs[page.id](ctx):supplementary(page.id,ctx)+table(page.id,ctx,page.title==='Equipos'?'Inventario de equipos':page.title);
}
function canPrimary(p,c){if(p.id==='equipo'&&!scoped(D.devices,c).some(d=>d.id===(c.id||'d1')))return false;if(p.id==='miembro'&&!scoped(D.people,c).some(d=>d.id===(c.id||'p1')))return false;return can(p.id,c)&&c.state==='normal'&&(['export','controls'].includes(p.kind)||(p.kind==='pending'&&can('pendientes',c))||canEdit(c));}
function render(pageId,options={}){const p=pageById(pageId),ctx=C(options);return `<a class="skip" href="#main">Saltar al contenido</a><aside class="sidebar" id="sidebar" aria-label="Navegación lateral"><a class="brand" href="${E(href('index',ctx))}"><img src="logo-mark.png" width="294" height="364" alt=""><span><strong>AZC<span>Keeper</span></strong><small>Administración · v4</small></span></a><button class="icon-button sidebar-close" data-action="close-menu" aria-label="Cerrar menú">${icon('close')}</button><nav aria-label="Secciones del panel">${nav(p,ctx)}</nav><div class="sidebar-bottom"><span class="avatar">ED</span><div><strong>${E(D.admin)}</strong><small>${E(D.roles[ctx.role].label)}</small></div></div></aside><button class="backdrop" data-action="close-menu" aria-label="Cerrar menú" hidden></button><header class="topbar"><button class="icon-button mobile-menu" data-action="menu" aria-controls="sidebar" aria-expanded="false" aria-label="Abrir menú">${icon('menu')}</button><div class="tenant"><strong>${E(D.company)}</strong><small>Administración de empresa</small></div><div class="top-meta"><span class="help time">${E(D.asOf)} · Bogotá</span><span class="demo-pill">Datos ficticios</span><button class="review-button" data-action="review-tools" aria-expanded="false" aria-controls="review-tools">Revisar prototipo</button></div></header><main id="main" tabindex="-1"><nav class="breadcrumb" aria-label="Ruta de navegación">${link('index','Grupo AZC',ctx)}<span>/</span>${p.parent?link(p.parent,pageById(p.parent).title,ctx)+'<span>/</span>':''}<span>${E(p.title)}</span></nav><section id="review-tools" class="review-tools" hidden><p>Controles de demostración. Cambia el perfil para revisar permisos y alcance, o muestra un estado vacío o de error.</p><div class="toolbar"><label>Perfil<select id="profile-select">${Object.entries(D.roles).map(([id,r])=>`<option value="${id}"${id===ctx.role?' selected':''}>${E(r.label)}</option>`).join('')}</select></label><label>Estado de pantalla<select id="state-select">${[['normal','Con datos'],['empty','Vacío'],['error','Error']].map(([id,label])=>`<option value="${id}"${ctx.state===id?' selected':''}>${label}</option>`).join('')}</select></label><button data-action="reset-demo">Restablecer muestra</button></div></section><div class="page-head"><div><h1>${E(p.title)}</h1><p>${E(p.description)}</p></div>${canPrimary(p,ctx)?`<button class="primary" id="page-action" data-action="primary" ${p.id==='roles'&&(!D.gateCompany||!D.gatePermission)?'disabled':''}>${icon(p.kind==='export'?'releases':p.kind==='create'?'plus':'arrow')}${E(p.action)}</button>`:''}</div>${p.future?'<div class="notice future"><span class="badge">Próximamente</span><span>Vista previa del módulo previsto. Los cambios son borradores de demostración.</span></div>':''}<div id="page-content">${content(p,ctx)}</div><section id="local-drafts" class="draft" hidden></section><footer><span>AZCKeeper v4 · Grupo AZC · Prototipo local</span><span>Datos ficticios · America/Bogota · Septiembre 2026</span></footer></main><dialog id="modal" aria-labelledby="modal-title"><div class="dialog-head"><h2 id="modal-title"></h2><button class="icon-button" data-action="close-modal" aria-label="Cerrar diálogo">${icon('close')}</button></div><div class="dialog-body" id="modal-body"></div></dialog><div id="feedback" class="feedback" role="status" hidden></div><noscript><p class="notice">Activa JavaScript para usar filtros y acciones. Los enlaces y el contenido de las páginas funcionan sin él.</p></noscript>`;}
function csv(m,ctx){const quote=v=>'"'+String(v??'').replace(/^[=+@-]/,"'").replace(/"/g,'""')+'"';return '\ufeff'+[m.columns,...filtered(m,ctx).map(r=>r.cells)].map(r=>r.map(quote).join(';')).join('\r\n');}
function validConfirmation(expected,typed,reason){return typed===expected&&reason.trim().length>=5;}
function contrast(a,b){const luminance=h=>{const c=h.replace('#','').match(/../g).map(x=>parseInt(x,16)/255).map(x=>x<=.04045?x/12.92:((x+.055)/1.055)**2.4);return c[0]*.2126+c[1]*.7152+c[2]*.0722;};const x=luminance(a),y=luminance(b);return(Math.max(x,y)+.05)/(Math.min(x,y)+.05);}
const API={render,model,filtered,csv,can,canEdit,scoped,validConfirmation,contrast,pageById,data:D};
if(typeof module!=='undefined'){module.exports=API;return;}
root.KeeperPrototype=API;
const params=new URLSearchParams(location.search),pageId=document.body.dataset.page;
let ctx=C({role:D.roles[params.get('role')]?params.get('role'):'admin',state:['empty','error'].includes(params.get('state'))?params.get('state'):'normal',id:params.get('id')});
if(params.get('q'))ctx.filters.q=params.get('q');
if(pageId==='equipos'){if(params.get('status'))ctx.filters[3]=params.get('status');if(params.get('site'))ctx.filters[2]=params.get('site');}
const initial=JSON.stringify(D),storageKey='azc-k3-v4-prototype-20260929-v1';
let drafts=[],commands=[],storageAvailable=true,modalCallback=null,modalFocus=null;
try{const stored=JSON.parse(localStorage.getItem(storageKey)||'null');if(stored?.version===1){for(const key of ['people','devices','pending','tables','brand','company','gateCompany','gatePermission'])if(stored.data[key]!==undefined)D[key]=stored.data[key];drafts=stored.drafts||[];commands=stored.commands||[];}}catch{storageAvailable=false;}
const $=id=>document.getElementById(id);
function save(){try{localStorage.setItem(storageKey,JSON.stringify({version:1,data:Object.fromEntries(['people','devices','pending','tables','brand','company','gateCompany','gatePermission'].map(k=>[k,D[k]])),drafts,commands}));}catch{storageAvailable=false;}}
function notify(message){$('feedback').innerHTML=E(message)+(!storageAvailable?' Los cambios se conservan solo en esta página.':'')+' <button data-action="dismiss">Cerrar</button>';$('feedback').hidden=false;}
function renderDrafts(){const list=drafts.filter(d=>d.page===pageId);const device=ctx.id||'d1';const queued=commands.filter(c=>pageId==='equipo'?c.device===device:pageId==='endurecimiento');const box=$('local-drafts');box.hidden=!list.length&&!queued.length;box.innerHTML=(list.length?panel('Borradores de esta sesión',list.map(d=>`<article class="alert-item"><strong>${E(d.title)}</strong><p>${E(d.fields.map(([k,v])=>k+': '+v).join(' · '))}</p>${badge('Borrador')}</article>`).join('')):'')+(queued.length?panel('Órdenes simuladas',queued.map(c=>`<article class="alert-item"><strong>${E(c.action)} · ${E(c.hostname)}</strong><p>${E(c.reason)}</p>${badge('En cola')}<p class="help">Simulación local: sin confirmación de un agente.</p></article>`).join('')):'');}
function draw(){const oldFocus=document.activeElement,focusId=oldFocus?.id,focusAction=oldFocus?.dataset.action;document.body.innerHTML=render(pageId,ctx);renderDrafts();document.documentElement.style.setProperty('--accent',D.brand.primary);document.documentElement.style.setProperty('--brand-red',D.brand.accent);const active=document.querySelector('.nav-link[aria-current]');if(active){const navEl=active.closest('nav');navEl.scrollTop=Math.max(0,active.offsetTop-navEl.offsetTop-170);} $('sidebar').inert=window.innerWidth<=820;const target=focusId?$(focusId):focusAction?document.querySelector('[data-action="'+focusAction+'"]'):null;if(target)target.focus();}
function refreshTable(){const m=model(pageId,ctx);if(m&&$('table-results'))$('table-results').innerHTML=tableRows(m,ctx);}
function openModal(title,body){modalFocus=document.activeElement;$('modal-title').textContent=title;$('modal-body').innerHTML=body;$('modal').showModal();}
function closeModal(){const m=$('modal');m.close();modalCallback=null;if(modalFocus?.isConnected)modalFocus.focus();}
function field([label,type],i,value=''){const id='field-'+i;return `<label for="${id}">${E(label)}${Array.isArray(type)?`<select id="${id}" name="f${i}" required>${type.map(t=>`<option${t===value?' selected':''}>${E(t)}</option>`).join('')}</select>`:type==='textarea'?`<textarea id="${id}" name="f${i}" required maxlength="1200">${E(value)}</textarea>`:`<input id="${id}" name="f${i}" type="${type}" ${type==='number'?'min="1" max="1000"':type==='date'?'min="2026-09-01" max="2026-09-30"':''} required value="${E(value)}" maxlength="200">`}</label>`;}
function formModal(title,fields,callback,lead='Los cambios se aplican únicamente a esta muestra local.',submit='Guardar en muestra',values=[]){openModal(title,`<p>${E(lead)}</p><form id="modal-form">${fields.map((f,i)=>field(f,i,values[i]||'')).join('')}<p id="form-error" class="error-text" hidden></p><div class="dialog-footer"><button type="button" data-action="close-modal">Cancelar</button><button class="primary" type="submit">${E(submit)}</button></div></form>`);modalCallback=()=>{const f=$('modal-form');if(!f.reportValidity())return;const values=fields.map((_,i)=>f.elements['f'+i].value.trim());if(values.some(v=>!v)){const err=$('form-error');err.textContent='Completa los campos; no se aceptan valores vacíos.';err.hidden=false;return;}callback(values);};}
function audit(action,resource){D.tables.auditoria.rows.unshift([D.asOf,D.admin,action,resource,'Simulado']);}
function addDraft(title,fields){drafts.unshift({page:pageId,title,fields});save();renderDrafts();}
function confirmation(title,target,explanation,callback){openModal(title,`<p>${E(explanation)}</p><div class="notice">Escribe exactamente <strong>${E(target)}</strong> y documenta el motivo. La acción es una simulación local.</div><form id="confirm-form"><label for="confirm-target">Confirmación escrita<input id="confirm-target" name="target" autocomplete="off" required></label><label for="confirm-reason">Motivo (mínimo 5 caracteres)<textarea id="confirm-reason" name="reason" minlength="5" required></textarea></label><div class="dialog-footer"><button type="button" data-action="close-modal">Cancelar</button><button class="primary" type="submit" id="confirm-submit" disabled>Confirmar simulación</button></div></form>`);modalCallback=()=>{const f=$('confirm-form');if(!validConfirmation(target,f.elements.target.value,f.elements.reason.value))return;callback(f.elements.reason.value.trim());};}
function command(action,deviceId){if(!canEdit(ctx))return;const d=scoped(D.devices,ctx).find(d=>d.id===deviceId);if(!d)return;const copy={Borrar:'El borrado remoto elimina los datos del equipo y no puede deshacerse. Verifica el equipo y el respaldo antes de continuar.',Apagar:'El equipo se apagará y puede perder trabajo sin guardar.',Reiniciar:'La sesión se interrumpirá y puede perder trabajo sin guardar.',Bloquear:'Se impedirá utilizar la sesión hasta que se autorice el desbloqueo.',Desbloquear:'La persona podrá volver a utilizar la sesión.'};confirmation(action+' · '+d.hostname,d.hostname,copy[action]||'Se modificará la configuración local de privilegios del equipo.',reason=>{commands.unshift({action,device:d.id,hostname:d.hostname,reason});audit(action,d.hostname);save();closeModal();renderDrafts();notify('Orden simulada en cola. No se ha enviado ni ejecutado ningún comando.');});}
function create(){if(!canEdit(ctx))return;const p=pageById(pageId),fields=D.forms[pageId]||[['Nombre','text'],['Descripción','textarea']];formModal(p.action,fields,values=>{
 if(pageId==='turnos'&&values[1]>=values[2]){$('form-error').hidden=false;$('form-error').textContent='La hora final debe ser posterior a la hora inicial.';return;}
 if(pageId==='usuarios'){if(D.people.some(p=>normalize(p.email)===normalize(values[1]))){$('form-error').hidden=false;$('form-error').textContent='Ya existe una persona con este correo en la muestra.';return;}D.people.push({id:'p-local-'+D.people.length,name:values[0],email:values[1],site:values[2],area:values[3],position:'Sin cargo asignado',tier:'Esencial',status:'Activo',presence:'Sin registro',entry:'Sin registro',focus:0,activeMinutes:0});}
 else if(pageId==='equipos'){if(D.devices.some(d=>normalize(d.hostname)===normalize(values[0]))){$('form-error').hidden=false;$('form-error').textContent='Ya existe un equipo con este nombre.';return;}D.devices.push({...D.devices[0],id:'d-local-'+D.devices.length,hostname:values[0],site:values[1],personId:D.people.find(p=>p.name===values[2]).id,status:'Sin conexión',version:'Sin reporte',lastSeen:'Esperando primer contacto',os:'Sin reporte',cpu:'Sin reporte',ram:'Sin reporte',disk:'Sin reporte',free:0,policy:'Pendiente',hardening:'Desconocido'});}
 else addDraft(values[0],fields.map((f,i)=>[f[0],values[i]]));
 audit(p.action,values[0]);save();closeModal();draw();notify(['usuarios','equipos'].includes(pageId)?'Registro añadido a la muestra.':'Borrador guardado en la muestra. No se publica ni se envía.');
 },p.future?'Vista previa: completa el formulario para guardar un borrador local. Esta función todavía no está implementada en el producto.':'Completa los datos para revisar el flujo. Ningún cambio se envía al sistema real.',p.future?'Guardar borrador':'Guardar en muestra');}
function review(index){if(pageId==='pendientes'){const p=D.pending[index];if(!p)return;openModal('Solicitud de acceso',facts([['Persona',E(p.name)],['Equipo',E(p.hostname)],['Sede',E(p.site)],['Recibida',E(p.date)],['Estado',badge(p.status)]])+`<p class="spaced">Confirma que la persona y el equipo pertenecen a la sede indicada.</p>${p.status==='Pendiente'&&canEdit(ctx)?`<div class="dialog-footer"><button class="danger" data-action="reject" data-index="${index}">Rechazar…</button><button class="primary" data-action="approve" data-index="${index}">Aprobar en muestra</button></div>`:''}`);return;}
 if(pageId==='doble-empleo'){const r=D.tables[pageId].rows[index];if(!r)return;formModal('Revisión de la señal',[['Resultado',['Revisada','Descartada','Pendiente']],['Motivo de la decisión','textarea']],values=>{r[4]=values[0];audit('Revisar señal',r[0]);addDraft('Revisión de '+r[0],[['Resultado',values[0]],['Motivo',values[1]]]);save();closeModal();draw();notify('Revisión guardada en la muestra.');},r[0]+' · '+r[1]+'. Esta señal requiere contexto y no prueba doble empleo.');}}
function rowDetails(index){const m=model(pageId,ctx),r=m?.rows[index];if(!r)return;if((pageId==='pendientes'||pageId==='doble-empleo')&&canEdit(ctx)){review(index);return;}openModal('Detalle · '+r[0],facts(m.columns.map((c,i)=>[c,E(r[i])]),true)+(pageId==='administradores'&&canEdit(ctx)?`<div class="dialog-footer"><button class="danger" data-action="revoke-admin" data-index="${index}">Revocar acceso…</button></div>`:'')+(pageId==='integraciones'&&canEdit(ctx)?'<div class="notice spaced">Vista previa de la integración. No hay credenciales reales ni entregas de red.</div>':''));}
function roleCreate(){if(!canEdit(ctx)||!D.gateCompany||!D.gatePermission)return;openModal('Crear rol de empresa',`<p>El rol empieza sin permisos. Ambos requisitos están habilitados para esta simulación.</p><form id="role-form"><label>Nombre del rol<input name="name" required maxlength="80"></label><label>Alcance<select name="scope"><option>Empresa</option><option>Sede asignada</option><option>Área asignada</option></select></label><fieldset><legend>Permisos explícitos</legend>${D.permissions.filter(p=>p!=='roles.gestionar').map(p=>`<label class="check"><input type="checkbox" name="permissions" value="${p}">${E(p)}</label>`).join('')}</fieldset><p class="help spaced">La delegación de roles.gestionar se reserva a la autoridad central.</p><div class="dialog-footer"><button type="button" data-action="close-modal">Cancelar</button><button type="submit" class="primary">Crear en muestra</button></div></form>`);modalCallback=()=>{if(!D.gateCompany||!D.gatePermission)return;const f=$('role-form');if(!f.reportValidity()||!f.elements.name.value.trim())return;const perm=[...f.querySelectorAll('[name=permissions]:checked')].map(i=>i.value);const name=f.elements.name.value.trim();D.tables.roles.rows.push([name,f.elements.scope.value,perm.includes('equipos.comandos')?'Gestionar':perm.includes('equipos.ver')?'Consultar':'Sin acceso',perm.includes('usuarios.editar')?'Gestionar':perm.includes('usuarios.ver')?'Consultar':'Sin acceso','Sin acceso']);addDraft(name,[['Alcance',f.elements.scope.value],['Permisos',perm.join(', ')||'Sin permisos']]);audit('Crear rol',name);save();closeModal();draw();notify('Rol de muestra creado con los permisos seleccionados.');};}
function brandPreview(){const f=$('brand-form');if(!f)return;$('preview-name').textContent=f.elements.company.value;const b=$('brand-preview');b.style.setProperty('--accent',f.elements.primary.value);b.style.borderBottom='3px solid '+f.elements.accent.value;}
function saveBrand(){if(!canEdit(ctx))return;const f=$('brand-form');if(!f.reportValidity())return;const color=f.elements.primary.value;if(contrast(color,'#F8F8F8')<4.5||contrast(color,'#E4E4E4')<4.5){$('brand-error').hidden=false;$('brand-error').textContent='El color principal necesita contraste de al menos 4,5:1 sobre el fondo y con el texto del botón. Elige un tono más oscuro.';return;}D.company=f.elements.company.value.trim()||D.company;D.brand={primary:color,accent:f.elements.accent.value};audit('Guardar marca',D.company);save();draw();notify('Marca de muestra guardada para Grupo AZC.');}
function exportData(){const m=model(pageId,ctx)||{columns:['Indicador','Valor'],rows:pageId==='salud'?Object.entries(D.health):D.activity.map(r=>[r[0],r[1]+'%']),filters:[]};const text=csv(m,ctx),url=URL.createObjectURL(new Blob([text],{type:'text/csv;charset=utf-8'})),a=document.createElement('a');a.href=url;a.download='azckeeper-'+pageId+'-2026-09-29.csv';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);notify('CSV generado con los registros que coinciden con los filtros.');}
function primary(){const p=pageById(pageId);if(!canPrimary(p,ctx))return;switch(p.kind){case'pending':location.href=href('pendientes',ctx);break;case'export':exportData();break;case'create':create();break;case'controls':$('controles')?.scrollIntoView({block:'start'});$('controles')?.focus();break;case'review':{const m=model(pageId,ctx),i=m.rows.findIndex(r=>r.at(-1)==='Pendiente');if(i<0)notify('No quedan registros pendientes por revisar.');else review(i);break;}case'role':roleCreate();break;case'settings':saveBrand();break;case'person':{const p=scoped(D.people,ctx).find(p=>p.id===(ctx.id||'p1'));if(!p)return;formModal('Editar persona',D.forms.usuarios,values=>{Object.assign(p,{name:values[0],email:values[1],site:values[2],area:values[3]});audit('Editar persona',p.name);save();closeModal();draw();notify('Persona actualizada en la muestra.');},undefined,undefined,[p.name,p.email,p.site,p.area]);break;}case'deploy':formModal('Preparar despliegue',[['Versión',['4.0.3','4.0.2']],['Anillo',['Piloto','Temprano','General']],['Ventana','datetime-local']],v=>{addDraft('Despliegue '+v[0],[['Anillo',v[1]],['Ventana',v[2]],['Estado','Esperando aprobación']]);closeModal();notify('Despliegue preparado como borrador. No se distribuye ningún paquete.');},'Se revisa la firma y se empieza por un anillo de alcance limitado. Esta vista no distribuye paquetes.','Guardar borrador');break;case'harden':hardeningReview(ctx.id||'d1');break;case'pin':formModal('Preparar bloqueo con PIN',[['Equipo',D.devices.slice(0,20).map(d=>d.hostname)],['Vigencia',['15 minutos','30 minutos']],['Motivo','textarea']],v=>{addDraft('Bloqueo con PIN',[['Equipo',v[0]],['Vigencia',v[1]],['Motivo',v[2]]]);closeModal();notify('Borrador de bloqueo con PIN guardado. No se generó ni envió un código.');},'Vista previa. El equipo no se bloquea y no se genera un PIN real.','Guardar borrador');break;}}
function hardeningReview(deviceId){const d=D.devices.find(d=>d.id===deviceId)||D.devices[0];openModal('Revisión de Modo B',facts([['Equipo',E(d.hostname)],['Cuenta de soporte',E(D.hardening.account)],['Custodia',E(D.hardening.recovery)],['Punto de restauración',badge('Fallido')]])+`<div class="notice spaced">La aplicación está bloqueada en este escenario: primero habilita la protección del sistema y confirma un punto de restauración.</div><div class="dialog-footer"><button data-action="close-modal">Entendido</button><a class="button" href="${E(href('equipo',ctx,{id:d.id}))}">Ver controles del equipo</a></div>`);}
function toggleMenu(open){const side=$('sidebar');side.inert=!open&&window.innerWidth<=820;side.classList.toggle('open',open);document.querySelector('.backdrop').hidden=!open;const button=document.querySelector('[data-action=menu]');button.setAttribute('aria-expanded',String(open));if(open){side.setAttribute('role','dialog');side.setAttribute('aria-modal','true');$('main').inert=true;document.querySelector('.topbar').inert=true;document.body.style.overflow='hidden';side.querySelector('[data-action=close-menu]').focus();}else{side.removeAttribute('role');side.removeAttribute('aria-modal');$('main').inert=false;document.querySelector('.topbar').inert=false;document.body.style.overflow='';button.focus();}}
document.addEventListener('click',event=>{const b=event.target.closest('[data-action]');if(!b)return;const action=b.dataset.action;switch(action){case'primary':primary();break;case'menu':toggleMenu(true);break;case'close-menu':toggleMenu(false);break;case'review-tools':{const box=$('review-tools');box.hidden=!box.hidden;b.setAttribute('aria-expanded',String(!box.hidden));break;}case'close-modal':closeModal();break;case'dismiss':$('feedback').hidden=true;break;case'clear-filters':ctx.filters={};ctx.page=1;document.querySelectorAll('[data-filter]').forEach(el=>el.value='');refreshTable();break;case'prev':ctx.page--;refreshTable();break;case'next':ctx.page++;refreshTable();break;case'restore':ctx.state='normal';draw();notify('Datos de muestra recuperados.');break;case'row':rowDetails(Number(b.dataset.index));break;case'command':command(b.dataset.command,b.dataset.device);break;case'harden-device':hardeningReview(b.dataset.device);break;case'revert-hardening':command('Revertir Modo B',b.dataset.device);break;case'approve':{if(!canEdit(ctx))break;const p=D.pending[Number(b.dataset.index)];p.status='Aprobada';audit('Aprobar acceso',p.hostname);save();closeModal();draw();notify('Acceso aprobado en la muestra. El equipo esperaría su primer contacto.');break;}case'reject':{const i=Number(b.dataset.index),p=D.pending[i];confirmation('Rechazar acceso',p.hostname,'Esta persona no podrá enrolar el equipo con esta solicitud.',reason=>{p.status='Rechazada';audit('Rechazar acceso',p.hostname);addDraft('Acceso rechazado',[['Equipo',p.hostname],['Motivo',reason]]);save();closeModal();draw();notify('Solicitud rechazada en la muestra.');});break;}case'revoke':if(canEdit(ctx))confirmation('Revocar clave API',b.dataset.target,'La integración perderá acceso con esta clave.',reason=>{D.tables.integraciones.rows[0][4]='Revocado';audit('Revocar clave',b.dataset.target);addDraft('Revocación de clave',[['Referencia',b.dataset.target],['Motivo',reason]]);save();closeModal();draw();notify('Revocación simulada. No existe ninguna clave real.');});break;case'revoke-admin':{const r=D.tables.administradores.rows[Number(b.dataset.index)];confirmation('Revocar acceso administrativo',r[1],'Esta cuenta perderá acceso administrativo al panel.',reason=>{r[4]='Revocado';audit('Revocar acceso',r[1]);addDraft('Acceso revocado',[['Cuenta',r[1]],['Motivo',reason]]);save();closeModal();draw();notify('Acceso administrativo revocado en la muestra.');});break;}case'capture':{const r=D.screenshots[Number(b.dataset.index)];openModal('Captura de muestra · '+r[0],`<div class="capture-screen"><div class="window-top">${E(r[1])}</div><div class="document-mock"><span></span><span></span><span></span><span></span></div></div><p class="spaced">${E(D.devices[0].hostname)} · ${E(D.people[0].name)} · 29 sep 2026, ${r[0]} · America/Bogota.</p><p>Ilustración con HTML y CSS. No contiene una captura real.</p>`);break;}case'reset-demo':{const fresh=JSON.parse(initial);Object.keys(fresh).forEach(k=>D[k]=fresh[k]);drafts=[];commands=[];save();ctx=C({role:ctx.role});draw();notify('Muestra restablecida.');break;}}});
document.addEventListener('input',event=>{const el=event.target;if(el.matches('[data-filter]')){ctx.filters[el.dataset.filter]=el.value;ctx.page=1;refreshTable();}if(el.closest('#brand-form'))brandPreview();if(el.closest('#confirm-form')){const f=$('confirm-form'),target=$('modal-body').querySelector('.notice strong').textContent;$('confirm-submit').disabled=!validConfirmation(target,f.elements.target.value,f.elements.reason.value);}});
document.addEventListener('change',event=>{const el=event.target;if(el.id==='profile-select'){const url=new URL(location.href);url.searchParams.set('role',el.value);location.href=url.href;return;}if(el.id==='state-select'){ctx.state=el.value;draw();$('review-tools').hidden=false;document.querySelector('[data-action=review-tools]').setAttribute('aria-expanded','true');return;}if(el.id==='gate-company'||el.id==='gate-permission'){D.gateCompany=$('gate-company').checked;D.gatePermission=$('gate-permission').checked;save();$('page-action').disabled=!D.gateCompany||!D.gatePermission;$('gate-status').textContent=D.gateCompany&&D.gatePermission?'Ambas autorizaciones están habilitadas. Puedes crear un rol de muestra.':'La edición está bloqueada. Se necesitan las dos autorizaciones.';}if(el.matches('select[data-filter]')){ctx.filters[el.dataset.filter]=el.value;ctx.page=1;refreshTable();}});
document.addEventListener('submit',event=>{event.preventDefault();if(event.target.closest('#modal'))modalCallback?.();else if(event.target.id==='brand-form')saveBrand();});
document.addEventListener('cancel',event=>{if(event.target.id==='modal'){event.preventDefault();closeModal();}},true);
document.addEventListener('keydown',event=>{const side=$('sidebar');if(!side?.classList.contains('open'))return;if(event.key==='Escape'){event.preventDefault();toggleMenu(false);}if(event.key==='Tab'){const nodes=[...side.querySelectorAll('a,button,summary')].filter(n=>n.getClientRects().length);const first=nodes[0],last=nodes.at(-1);if(event.shiftKey&&document.activeElement===first){event.preventDefault();last.focus();}else if(!event.shiftKey&&document.activeElement===last){event.preventDefault();first.focus();}}});
window.addEventListener('resize',()=>{if(window.innerWidth>820&&$('sidebar')?.classList.contains('open'))toggleMenu(false);$('sidebar').inert=window.innerWidth<=820&&!$('sidebar').classList.contains('open');});
draw();
})(typeof window!=='undefined'?window:globalThis);
